	in_TerCRC     int unsigned,
	in_GeoIdxCRC  int unsigned,
	in_GeoDatCRC  int unsigned,
	in_ObjectsCRC int unsigned,
	in_ForestCRC  int unsigned
)
BEGIN
	update terrain_blocks set
		`TerCRC`     = in_TerCRC,
		`GeoIdxCRC`  = in_GeoIdxCRC,
		`GeoDatCRC`  = in_GeoDatCRC,
		`ObjectsCRC` = in_ObjectsCRC,
		`ForestCRC`  = in_ForestCRC
		where ID=in_terID;
END;


