		values(in_TerID, in_ChangeID, in_Action, in_ObjectSuperType, in_ObjectID, in_GeoDataID, in_ObjectTypeID, in_TurnAngle, in_Altitude, in_OffsetX, in_OffsetY, in_OffsetZ, in_IsComplete, in_Slope);
	
	update terrain_blocks
		set ObjectsVersion = in_ChangeID
		where ID = in_TerID and ObjectsVersion < in_ChangeID; -- do not downgrade version

/*
	return versionID;
*/
END;


