-- Dumping structure for function cm.f_addForestPatch
DROP FUNCTION IF EXISTS `f_addForestPatch`;
CREATE FUNCTION `f_addForestPatch`(
	`in_TerID` INT UNSIGNED,
	`in_Action` TINYINT UNSIGNED,
	`in_GeoDataID` INT UNSIGNED,
	`in_SubcellMask` TINYINT UNSIGNED,
	`in_TreeType` TINYINT UNSIGNED,
	`in_TreeHealth` TINYINT UNSIGNED,
	`in_AddTime` TINYINT UNSIGNED
) RETURNS int(10) unsigned
    MODIFIES SQL DATA
BEGIN
	
	declare versionID, dummyTerID INT UNSIGNED default NULL;

	/* get current objects version for this terrain */
	select ForestVersion, ID from terrain_blocks
		where ID = in_TerID limit 1
		into versionID, dummyTerID
		for update;
	
	/* check terrain */
	if(dummyTerID is null) then
		return NULL;
	end if;
	
	/* increment version */
	set versionID = (ifnull(versionID, 0) + 1);
	
	/* make changes */
		values(in_TerID, versionID, in_Action, in_GeoDataID, in_SubcellMask, in_TreeType, in_TreeHealth, in_AddTime);
	
	update terrain_blocks
		set ForestVersion = versionID
		where ID = in_TerID;
	
	return versionID;
	
END;


-- Dumping structure for function cm.f_addGeoPatch
DROP FUNCTION IF EXISTS `f_addGeoPatch`;
CREATE FUNCTION `f_addGeoPatch`(
	`isFirstChange` TINYINT UNSIGNED,
	`in_IsServerOnly` TINYINT UNSIGNED,
	`in_TerID` INT UNSIGNED,
	`in_Action` TINYINT UNSIGNED,
	`in_GeoDataID` INT UNSIGNED,
	`in_Altitude` SMALLINT UNSIGNED,
	`in_Substance` TINYINT UNSIGNED,
	`in_LevelFlags` TINYINT UNSIGNED,
	`in_Quantity` SMALLINT UNSIGNED,
	`in_Quality` TINYINT UNSIGNED
) RETURNS int(10) unsigned
    MODIFIES SQL DATA
BEGIN
	
	declare versionID, dummyTerID, changeIdx INT UNSIGNED default NULL;

	/* get current objects version for this terrain */
	select GeoVersion, ID from terrain_blocks
		where ID = in_TerID limit 1
		into versionID, dummyTerID
		for update;
	
	/* check terrain */
	if(dummyTerID is null) then
		return NULL;
	end if;
	
	/* increment version if this is initial change */
	if(isFirstChange > 0) then
		set versionID = (ifnull(versionID, 0) + 1);
		set changeIdx = 1;
	else
		select max(ChangeIndex) from geo_patch
			where `TerID` = in_TerID and `Version` = versionID
			into changeIdx;
		
		/* check index */
		if(changeIdx is null) then
			return NULL; -- invalid change index (may be this change is actually first one?)
		end if;
		
		set changeIdx = (changeIdx + 1);
	end if;
	
	/* make changes */
		values(in_TerID, versionID, changeIdx,     in_IsServerOnly, in_Action, in_GeoDataID, in_Altitude, in_Substance, in_LevelFlags, in_Quantity, in_Quality);
	
	update terrain_blocks
		set GeoVersion = versionID
		where ID = in_TerID and GeoVersion != versionID;
	
	return versionID;
	
END;


