-- Dumping structure for function cm.f_createRootContainer
DROP FUNCTION IF EXISTS `f_createRootContainer`;
CREATE FUNCTION `f_createRootContainer`(
	containerName varchar(64)
) RETURNS int(10)
    MODIFIES SQL DATA
BEGIN
	declare containerID, typeID int default NULL;
	SELECT ID FROM objects_types
		WHERE Name = containerName COLLATE utf8_unicode_ci and IsContainer = 1
		LIMIT 1 INTO typeID;
	/* container */
	if(typeID is not null) then
		SET containerID =f_createContainer( NULL, typeID, 0);
	end if;
	return containerID;
END;


-- Dumping structure for function cm.f_dayEnd
DROP FUNCTION IF EXISTS `f_dayEnd`;
CREATE FUNCTION `f_dayEnd`() RETURNS int(10) unsigned
BEGIN
	
	declare currDayNum int unsigned default NULL;
	select max(ID) from day_version into currDayNum for update;
	
	if(currDayNum is null) then
		return NULL;
	end if;
	
	if(exists(select * from day_version where ID=currDayNum and `End` is null)) then
		update day_version set `End`=now()
			where ID = currDayNum;
	end if;

	return currDayNum;
END;


-- Dumping structure for function cm.f_dayNumber
DROP FUNCTION IF EXISTS `f_dayNumber`;
CREATE FUNCTION `f_dayNumber`() RETURNS int(10) unsigned
BEGIN
	declare lastDayNum int unsigned default NULL;
	select max(ID) from day_version into lastDayNum for update;
	
	-- check if day started
	if(exists(select * from day_version where ID=lastDayNum and `Begin` is not null and `End` is null)) then
		return lastDayNum;
	end if;

	return NULL; -- day was not started yet
END;


-- Dumping structure for function cm.f_dayStart
DROP FUNCTION IF EXISTS `f_dayStart`;
CREATE FUNCTION `f_dayStart`() RETURNS int(10) unsigned
BEGIN
	declare lastDayNum int unsigned default NULL;
	select max(ID) from day_version into lastDayNum for update;
	
	-- check if day already started (day ends only at maintenance)
	if(exists(select * from day_version where ID=lastDayNum and `End` is null)) then
		return lastDayNum;
	end if;


	return LAST_INSERT_ID(); -- return current day number
END;


