-- Dumping structure for function cm.f_insertNewItemInventory
DROP FUNCTION IF EXISTS `f_insertNewItemInventory`;
CREATE FUNCTION `f_insertNewItemInventory`(`ContainerID` INT UNSIGNED, `ItemTypeID` INT UNSIGNED, `Quality` TINYINT UNSIGNED, `Quantity` INT UNSIGNED, `CreatedDurability` SMALLINT UNSIGNED, `Durability` SMALLINT UNSIGNED, `pFeatureText` VARCHAR(255), `pEffect1ID` TINYINT, `pEffect1Magnitude` SMALLINT, `pEffect2ID` TINYINT, `pEffect2Magnitude` SMALLINT, `pEffect3ID` TINYINT, `pEffect3Magnitude` SMALLINT) RETURNS int(11)
BEGIN

	DECLARE itemID INT UNSIGNED default 0;
	DECLARE customTextID INT UNSIGNED default NULL;
	DECLARE haveEffects TINYINT default 0;
	DECLARE featureID INT UNSIGNED default NULL;

	/* use this code wnen items.ID field close to its upper limit
	
	start transaction;
	
	select (i1.id + 1) as free_id
	from items as i1
	left join items as i2 on (i1.id + 1) = i2.id
	where i2.id is null
	limit 1
	into itemID
	for update;
	
	use itemID for insert below
	*/
	
		VALUES(ContainerID, ItemTypeID, Quality, Quantity, Durability, CreatedDurability);
	SET itemID = LAST_INSERT_ID();

	if( LENGTH(IFNULL(pFeatureText, '')) > 0) then
		SET customTextID =f_insertCustomText( pFeatureText);
	end if;

	if( pEffect1ID >0) then
			VALUES (itemID, pEffect1ID, pEffect1Magnitude);
		SET haveEffects =1;
	end if;
	if( pEffect2ID >0) then
			VALUES (itemID, pEffect2ID, pEffect2Magnitude);
		SET haveEffects =1;
	end if;
	if( pEffect3ID >0) then
			VALUES (itemID, pEffect3ID, pEffect3Magnitude);
		SET haveEffects =1;
	end if;

	if( customTextID is not NULL OR haveEffects !=0) then
		SET featureID =LAST_INSERT_ID();
		UPDATE items SET `FeatureID` =featureID WHERE ID =itemID;
	end if;
	
	return itemID;
	
	/*commit;*/

END;


